-- LANGKAH 1: CREATE 10 TABEL BESERTA CONSTRAINT
CREATE TABLE "USER" (
    USER_ID NUMBER(6) NOT NULL,
    USERNAME VARCHAR2(200) NOT NULL,
    EMAIL VARCHAR2(400) NOT NULL,
    PASSWORD VARCHAR2(1020) NOT NULL,
    ROLE VARCHAR2(40) DEFAULT 'user' NOT NULL,
    PHONE VARCHAR2(80) DEFAULT '-',
    ADDRESS VARCHAR2(1020) DEFAULT '-',
    NAME VARCHAR2(200),
    BIO VARCHAR2(500),
    AVATAR VARCHAR2(500),
    REMEMBER_TOKEN VARCHAR2(100),
    CREATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_USER PRIMARY KEY (USER_ID),
    CONSTRAINT UQ_USER_USERNAME UNIQUE (USERNAME),
    CONSTRAINT UQ_USER_EMAIL UNIQUE (EMAIL),
    CONSTRAINT CK_USER_ROLE CHECK (UPPER(role) IN ('ADMIN', 'CUSTOMER', 'USER'))
);

CREATE TABLE PET (
    PET_ID NUMBER(6) NOT NULL,
    PET_NAME VARCHAR2(240) NOT NULL,
    SPECIES VARCHAR2(120) NOT NULL,
    BREED VARCHAR2(240) NOT NULL,
    GENDER VARCHAR2(40) NOT NULL,
    AGE NUMBER(4,1) NOT NULL,
    USER_ID NUMBER(6) NOT NULL,
    HEALTH_STATUS VARCHAR2(100) DEFAULT 'Sehat',
    CREATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_PET PRIMARY KEY (PET_ID),
    CONSTRAINT FK_PET_USER FOREIGN KEY (USER_ID) REFERENCES "USER" (USER_ID) ON DELETE CASCADE,
    CONSTRAINT CK_PET_AGE CHECK (age >= 0),
    CONSTRAINT CK_PET_GENDER CHECK (UPPER(gender) IN ('JANTAN', 'BETINA', 'MALE', 'FEMALE'))
);

CREATE TABLE ANIMAL (
    ANIMAL_ID NUMBER(6) NOT NULL,
    NAMA VARCHAR2(240) NOT NULL,
    SPECIES VARCHAR2(120) NOT NULL,
    BREED VARCHAR2(240) NOT NULL,
    GENDER VARCHAR2(40) NOT NULL,
    AGE NUMBER(4,1) NOT NULL,
    STATUS VARCHAR2(60) DEFAULT 'available' NOT NULL,
    IMAGE VARCHAR2(500) DEFAULT 'assets/img/meng.png',
    DESCRIPTION VARCHAR2(1000),
    CREATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_ANIMAL PRIMARY KEY (ANIMAL_ID),
    CONSTRAINT CK_ANIMAL_AGE CHECK (age >= 0),
    CONSTRAINT CK_ANIMAL_GENDER CHECK (UPPER(gender) IN ('JANTAN', 'BETINA', 'MALE', 'FEMALE')),
    CONSTRAINT CK_ANIMAL_STATUS CHECK (UPPER(status) IN ('TERSEDIA', 'DIADOPSI', 'AVAILABLE', 'ADOPTED', 'UNAVAILABLE'))
);

CREATE TABLE ADOPTION_REQUEST (
    ADOPTION_REQUEST_ID NUMBER(6) NOT NULL,
    REQUEST_DATE DATE NOT NULL,
    STATUS VARCHAR2(60) DEFAULT 'pending' NOT NULL,
    USER_ID NUMBER(6) NOT NULL,
    ANIMAL_ID NUMBER(6) NOT NULL,
    APPLICANT_NAME VARCHAR2(200),
    EMAIL VARCHAR2(200),
    PHONE VARCHAR2(60),
    ADDRESS VARCHAR2(1000),
    REASON VARCHAR2(1000),
    ADMIN_NOTE VARCHAR2(1000),
    CREATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_ADOPTION_REQUEST PRIMARY KEY (ADOPTION_REQUEST_ID),
    CONSTRAINT FK_ADOPTION_USER FOREIGN KEY (USER_ID) REFERENCES "USER" (USER_ID) ON DELETE CASCADE,
    CONSTRAINT FK_ADOPTION_ANIMAL FOREIGN KEY (ANIMAL_ID) REFERENCES ANIMAL (ANIMAL_ID) ON DELETE CASCADE,
    CONSTRAINT UQ_ADOPTION_USER_ANIMAL UNIQUE (USER_ID, ANIMAL_ID),
    CONSTRAINT CK_ADOPTION_STATUS CHECK (UPPER(status) IN ('MENUNGGU', 'DISETUJUI', 'DITOLAK', 'PENDING', 'APPROVED', 'REJECTED', 'CANCELLED', 'DIBATALKAN'))
);

CREATE TABLE PRODUCT (
    PRODUCT_ID NUMBER(6) NOT NULL,
    PRODUCT_NAME VARCHAR2(400) NOT NULL,
    PRICE NUMBER(12,2) NOT NULL,
    STOCK NUMBER(6) NOT NULL,
    CATEGORY VARCHAR2(160) NOT NULL,
    SLUG VARCHAR2(200),
    IMAGE VARCHAR2(500) DEFAULT 'assets/img/shop/whiskas.png',
    DESCRIPTION VARCHAR2(1000),
    CREATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_PRODUCT PRIMARY KEY (PRODUCT_ID),
    CONSTRAINT CK_PRODUCT_PRICE CHECK (price >= 0),
    CONSTRAINT CK_PRODUCT_STOCK CHECK (stock >= 0)
);

CREATE TABLE "ORDER" (
    ORDER_ID NUMBER(6) NOT NULL,
    ORDER_DATE DATE NOT NULL,
    TOTAL_PRICE NUMBER(12,2) NOT NULL,
    STATUS VARCHAR2(60) DEFAULT 'pending' NOT NULL,
    USER_ID NUMBER(6) NOT NULL,
    ORDER_CODE VARCHAR2(80),
    RECIPIENT_NAME VARCHAR2(200),
    RECIPIENT_PHONE VARCHAR2(60),
    DELIVERY_METHOD VARCHAR2(40) DEFAULT 'pickup',
    SHIPPING_ADDRESS VARCHAR2(1000),
    SHIPPING_FEE NUMBER DEFAULT 0,
    CREATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_ORDER PRIMARY KEY (ORDER_ID),
    CONSTRAINT FK_ORDER_USER FOREIGN KEY (USER_ID) REFERENCES "USER" (USER_ID) ON DELETE CASCADE,
    CONSTRAINT CK_ORDER_TOTAL CHECK (total_price >= 0),
    CONSTRAINT CK_ORDER_STATUS CHECK (UPPER(status) IN ('MENUNGGU', 'DIPROSES', 'DIKIRIM', 'SELESAI', 'DIBATALKAN', 'PENDING', 'PROCESSING', 'SHIPPED', 'COMPLETED', 'CANCELLED'))
);

CREATE OR REPLACE VIEW ORDERS AS SELECT * FROM "ORDER";

CREATE TABLE ORDER_DETAIL (
    ORDER_DETAIL_ID NUMBER(6) NOT NULL,
    QUANTITY NUMBER(6) NOT NULL,
    ORDER_ID NUMBER(6) NOT NULL,
    PRODUCT_ID NUMBER(6) NOT NULL,
    UNIT_PRICE NUMBER DEFAULT 0,
    SUBTOTAL NUMBER DEFAULT 0,
    CREATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_ORDER_DETAIL PRIMARY KEY (ORDER_DETAIL_ID),
    CONSTRAINT FK_DETAIL_ORDER FOREIGN KEY (ORDER_ID) REFERENCES "ORDER" (ORDER_ID) ON DELETE CASCADE,
    CONSTRAINT FK_DETAIL_PRODUCT FOREIGN KEY (PRODUCT_ID) REFERENCES PRODUCT (PRODUCT_ID) ON DELETE CASCADE,
    CONSTRAINT UQ_DETAIL_ORDER_PRODUCT UNIQUE (ORDER_ID, PRODUCT_ID),
    CONSTRAINT CK_DETAIL_QUANTITY CHECK (quantity > 0)
);

CREATE TABLE HEALTH_SERVICE (
    SERVICE_ID NUMBER(6) NOT NULL,
    SERVICE_NAME VARCHAR2(400) NOT NULL,
    PRICE NUMBER(12,2) NOT NULL,
    DOCTOR_NAME VARCHAR2(200) DEFAULT 'drh. Clara Wijaya',
    PRACTICE_DAYS VARCHAR2(200) DEFAULT 'Senin - Sabtu',
    TIME_SLOTS VARCHAR2(200) DEFAULT '09:00, 13:00, 16:00',
    DAILY_QUOTA NUMBER DEFAULT 5,
    DESCRIPTION VARCHAR2(1000),
    ICON VARCHAR2(40) DEFAULT '🩺',
    CARD_COLOR VARCHAR2(60) DEFAULT 'card-green',
    CREATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_HEALTH_SERVICE PRIMARY KEY (SERVICE_ID),
    CONSTRAINT UQ_SERVICE_NAME UNIQUE (SERVICE_NAME),
    CONSTRAINT CK_SERVICE_PRICE CHECK (price >= 0)
);

CREATE TABLE HEALTH_BOOKING (
    BOOKING_ID NUMBER(6) NOT NULL,
    BOOKING_DATE DATE NOT NULL,
    STATUS VARCHAR2(60) DEFAULT 'pending' NOT NULL,
    USER_ID NUMBER(6) NOT NULL,
    SERVICE_ID NUMBER(6) NOT NULL,
    PET_ID NUMBER,
    OWNER_NAME VARCHAR2(200),
    PET_NAME VARCHAR2(200),
    PET_SPECIES VARCHAR2(100),
    REJECTION_REASON VARCHAR2(1000),
    CREATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_HEALTH_BOOKING PRIMARY KEY (BOOKING_ID),
    CONSTRAINT FK_BOOKING_USER FOREIGN KEY (USER_ID) REFERENCES "USER" (USER_ID) ON DELETE CASCADE,
    CONSTRAINT FK_BOOKING_SERVICE FOREIGN KEY (SERVICE_ID) REFERENCES HEALTH_SERVICE (SERVICE_ID) ON DELETE CASCADE,
    CONSTRAINT CK_BOOKING_STATUS CHECK (UPPER(status) IN ('TERJADWAL', 'SELESAI', 'DIBATALKAN', 'MENUNGGU', 'DISETUJUI', 'DITOLAK', 'PENDING', 'APPROVED', 'REJECTED', 'COMPLETED', 'CANCELLED'))
);

CREATE TABLE PAYMENT (
    PAYMENT_ID NUMBER(6) NOT NULL,
    METHOD VARCHAR2(80) DEFAULT 'TRANSFER_BANK',
    AMOUNT NUMBER(12,2) NOT NULL,
    STATUS VARCHAR2(60) DEFAULT 'MENUNGGU' NOT NULL,
    CREATED_AT DATE DEFAULT SYSDATE,
    PAID_AT DATE,
    REFERENCE_NUMBER VARCHAR2(160),
    ORDER_ID NUMBER(6),
    BOOKING_ID NUMBER(6),
    PAYMENT_DATE TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    PAYMENT_METHOD VARCHAR2(100),
    PAYMENT_STATUS VARCHAR2(60),
    UPDATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_PAYMENT PRIMARY KEY (PAYMENT_ID),
    CONSTRAINT FK_PAYMENT_ORDER FOREIGN KEY (ORDER_ID) REFERENCES "ORDER" (ORDER_ID) ON DELETE CASCADE,
    CONSTRAINT FK_PAYMENT_BOOKING FOREIGN KEY (BOOKING_ID) REFERENCES HEALTH_BOOKING (BOOKING_ID) ON DELETE CASCADE,
    CONSTRAINT CK_PAYMENT_AMOUNT CHECK (amount > 0),
    CONSTRAINT CK_PAYMENT_METHOD CHECK (method IS NULL OR UPPER(method) IN ('TRANSFER_BANK', 'QRIS', 'TUNAI', 'COD', 'TRANSFER')),
    CONSTRAINT CK_PAYMENT_STATUS CHECK (status IS NULL OR UPPER(status) IN ('MENUNGGU', 'BERHASIL', 'GAGAL', 'PENDING', 'PAID', 'SUCCESS', 'FAILED', 'CANCELLED')),
    CONSTRAINT CK_PAYMENT_TARGET CHECK (order_id IS NOT NULL OR booking_id IS NOT NULL)
);

